import { TriviaQuestion } from '../trivia-types'

export const POP_CULTURE_QUESTIONS: TriviaQuestion[] = [
  { id: 'pop-1', category: 'pop-culture', difficulty: 'easy', question: 'What social media platform was originally called "TheFacebook"?', answer: 'Facebook', options: ['Myspace', 'Facebook', 'Twitter', 'LinkedIn'], explanation: 'Mark Zuckerberg launched "TheFacebook" in 2004 from his Harvard dorm room. The "The" was dropped in 2005 when the company acquired the domain facebook.com.' },
  { id: 'pop-2', category: 'pop-culture', difficulty: 'easy', question: 'What is the name of Mario\'s brother in the Nintendo franchise?', answer: 'Luigi', options: ['Wario', 'Luigi', 'Toad', 'Yoshi'], explanation: 'Luigi first appeared alongside Mario in the 1983 arcade game Mario Bros. He is typically depicted as taller and thinner than Mario, wearing green instead of red.' },
  { id: 'pop-3', category: 'pop-culture', difficulty: 'easy', question: 'Which company created the iPhone?', answer: 'Apple', options: ['Samsung', 'Apple', 'Google', 'Microsoft'], explanation: 'Steve Jobs unveiled the first iPhone on January 9, 2007. It combined a phone, widescreen iPod, and internet device into one product, revolutionizing the smartphone industry.' },
  { id: 'pop-4', category: 'pop-culture', difficulty: 'easy', question: 'What board game involves buying and trading properties?', answer: 'Monopoly', options: ['Risk', 'Clue', 'Monopoly', 'Scrabble'], explanation: 'Monopoly was first published by Parker Brothers in 1935. The game\'s properties are named after real streets in Atlantic City, New Jersey.' },
  { id: 'pop-5', category: 'pop-culture', difficulty: 'easy', question: 'What video game features the character Link as the main hero?', answer: 'The Legend of Zelda', options: ['Final Fantasy', 'The Legend of Zelda', 'Dragon Quest', 'Chrono Trigger'], explanation: 'Link is often mistakenly called Zelda, who is actually the princess he rescues. The first Legend of Zelda game was released in 1986 for the Nintendo Entertainment System.' },
  { id: 'pop-6', category: 'pop-culture', difficulty: 'easy', question: 'What toy building brick company is based in Denmark?', answer: 'LEGO', options: ['Mega Bloks', 'LEGO', 'K\'Nex', 'Lincoln Logs'], explanation: 'LEGO was founded in 1932 by Ole Kirk Christiansen. The name comes from the Danish phrase "leg godt," meaning "play well."' },
  { id: 'pop-7', category: 'pop-culture', difficulty: 'easy', question: 'Which platform is known for short-form video content and was developed by ByteDance?', answer: 'TikTok', options: ['Vine', 'TikTok', 'Instagram Reels', 'YouTube Shorts'], explanation: 'TikTok launched internationally in 2017 and merged with Musical.ly in 2018. ByteDance, the Chinese parent company, also operates a similar app called Douyin in China.' },
  { id: 'pop-8', category: 'pop-culture', difficulty: 'easy', question: 'What is the best-selling video game of all time (as of 2024)?', answer: 'Minecraft', options: ['Tetris', 'GTA V', 'Minecraft', 'Wii Sports'], explanation: 'Minecraft has sold over 300 million copies across all platforms. It was created by Markus "Notch" Persson and later acquired by Microsoft in 2014 for $2.5 billion.' },
  { id: 'pop-9', category: 'pop-culture', difficulty: 'easy', question: 'What company did Jeff Bezos found in 1994?', answer: 'Amazon', options: ['eBay', 'Amazon', 'Alibaba', 'Walmart'], explanation: 'Jeff Bezos started Amazon as an online bookstore in his garage in Bellevue, Washington. It has since grown into the world\'s largest online retailer.' },
  { id: 'pop-10', category: 'pop-culture', difficulty: 'easy', question: 'Which superhero is known as the "Man of Steel"?', answer: 'Superman', options: ['Batman', 'Iron Man', 'Superman', 'Captain America'], explanation: 'Superman first appeared in Action Comics #1 in 1938, created by Jerry Siegel and Joe Shuster. His alter ego is Clark Kent, a reporter at the Daily Planet.' },
  { id: 'pop-11', category: 'pop-culture', difficulty: 'easy', question: 'What is the slogan for Nike?', answer: 'Just Do It', options: ['Impossible Is Nothing', 'Just Do It', 'Think Different', 'Be All You Can Be'], explanation: 'Nike\'s "Just Do It" slogan was created by advertising agency Wieden+Kennedy in 1988. It was inspired in part by the last words of convicted murderer Gary Gilmore.' },
  { id: 'pop-12', category: 'pop-culture', difficulty: 'easy', question: 'What reality TV show features contestants competing on a deserted location for a million dollars?', answer: 'Survivor', options: ['The Amazing Race', 'Big Brother', 'Survivor', 'Fear Factor'], explanation: 'Survivor premiered on CBS in 2000 and became a massive cultural phenomenon. The first season was set in Borneo, and Jeff Probst has hosted the show since its debut.' },
  { id: 'pop-13', category: 'pop-culture', difficulty: 'easy', question: 'Which Pokemon is number one in the original Pokedex?', answer: 'Bulbasaur', options: ['Pikachu', 'Charmander', 'Bulbasaur', 'Squirtle'], explanation: 'Bulbasaur is a Grass/Poison-type Pokemon and one of the three original starter Pokemon. Despite Pikachu being the franchise mascot, Bulbasaur holds the #001 spot.' },
  { id: 'pop-14', category: 'pop-culture', difficulty: 'easy', question: 'What social media platform uses a blue bird (now "X") as its logo?', answer: 'Twitter', options: ['Facebook', 'Twitter', 'Tumblr', 'Mastodon'], explanation: 'Twitter was founded in 2006 by Jack Dorsey, Biz Stone, and Evan Williams. Elon Musk acquired the platform in 2022 and rebranded it to X.' },
  { id: 'pop-15', category: 'pop-culture', difficulty: 'easy', question: 'What fashion brand is known for its interlocking "CC" logo?', answer: 'Chanel', options: ['Gucci', 'Chanel', 'Louis Vuitton', 'Prada'], explanation: 'The double-C logo represents founder Coco Chanel\'s initials. Coco Chanel revolutionized women\'s fashion in the early 20th century by popularizing casual, comfortable elegance.' },
  { id: 'pop-16', category: 'pop-culture', difficulty: 'easy', question: 'What theme park is home to Cinderella Castle?', answer: 'Walt Disney World\'s Magic Kingdom', options: ['Disneyland', 'Walt Disney World\'s Magic Kingdom', 'Universal Studios', 'Six Flags'], explanation: 'Cinderella Castle stands 189 feet tall at the Magic Kingdom in Orlando, Florida. Disneyland in California has Sleeping Beauty Castle instead, which is much smaller.' },
  { id: 'pop-17', category: 'pop-culture', difficulty: 'easy', question: 'Who is the CEO of Tesla and SpaceX?', answer: 'Elon Musk', options: ['Jeff Bezos', 'Elon Musk', 'Bill Gates', 'Mark Zuckerberg'], explanation: 'Elon Musk co-founded PayPal before leading Tesla and founding SpaceX. He also acquired Twitter in 2022 and rebranded it as X.' },
  { id: 'pop-18', category: 'pop-culture', difficulty: 'easy', question: 'In the board game Clue, what are players trying to solve?', answer: 'A murder', options: ['A robbery', 'A kidnapping', 'A murder', 'A treasure hunt'], explanation: 'Players try to determine who killed Mr. Boddy, with what weapon, and in which room. The game was invented by Anthony Pratt in England during WWII, where it\'s called Cluedo.' },
  { id: 'pop-19', category: 'pop-culture', difficulty: 'easy', question: 'What video game franchise features a character named Master Chief?', answer: 'Halo', options: ['Call of Duty', 'Halo', 'Gears of War', 'Destiny'], explanation: 'Master Chief, also known as John-117, is a super-soldier fighting alien forces. The first Halo game launched in 2001 as a flagship title for Microsoft\'s Xbox console.' },
  { id: 'pop-20', category: 'pop-culture', difficulty: 'easy', question: 'Which comic book company created Spider-Man and the X-Men?', answer: 'Marvel', options: ['DC Comics', 'Marvel', 'Image Comics', 'Dark Horse'], explanation: 'Marvel Comics was founded in 1939 as Timely Comics. Spider-Man was created by Stan Lee and Steve Ditko, first appearing in Amazing Fantasy #15 in 1962.' },
  { id: 'pop-21', category: 'pop-culture', difficulty: 'easy', question: 'What Google-owned platform is the world\'s largest video sharing website?', answer: 'YouTube', options: ['Vimeo', 'YouTube', 'Dailymotion', 'Twitch'], explanation: 'YouTube was founded in 2005 by three former PayPal employees and acquired by Google in 2006 for $1.65 billion. The first video uploaded was "Me at the zoo."' },
  { id: 'pop-22', category: 'pop-culture', difficulty: 'easy', question: 'What slinky toy was originally invented as a what?', answer: 'A naval spring for stabilizing instruments', options: ['A doorstop', 'A naval spring for stabilizing instruments', 'A children\'s jump rope', 'A suspension spring for cars'], explanation: 'Naval engineer Richard James accidentally knocked a tension spring off a shelf in 1943 and watched it "walk" down. His wife Betty named it "Slinky" and it became a toy sensation.' },
  { id: 'pop-23', category: 'pop-culture', difficulty: 'easy', question: 'What is the name of the fictional city where Batman operates?', answer: 'Gotham City', options: ['Metropolis', 'Star City', 'Gotham City', 'Central City'], explanation: 'Gotham City first appeared in Batman #4 in 1940. Metropolis, by contrast, is Superman\'s home city. Both are often said to represent different aspects of New York City.' },
  { id: 'pop-24', category: 'pop-culture', difficulty: 'easy', question: 'What toy was the must-have Christmas gift in 1996, causing store riots?', answer: 'Tickle Me Elmo', options: ['Furby', 'Tickle Me Elmo', 'Tamagotchi', 'Beanie Babies'], explanation: 'Tickle Me Elmo, made by Tyco Toys, would giggle and vibrate when squeezed. The toy frenzy led to prices reaching hundreds of dollars on the secondary market.' },
  { id: 'pop-25', category: 'pop-culture', difficulty: 'easy', question: 'What does GTA stand for in the video game series?', answer: 'Grand Theft Auto', options: ['Grand Theft Auto', 'Great Tactical Adventure', 'Global Threat Assessment', 'Grand Tournament Arena'], explanation: 'The Grand Theft Auto series began in 1997 as a top-down game. GTA V, released in 2013, became one of the best-selling entertainment products of all time.' },
  { id: 'pop-26', category: 'pop-culture', difficulty: 'easy', question: 'What advertising mascot says "I\'m Lovin\' It"?', answer: 'McDonald\'s', options: ['Burger King', 'Wendy\'s', 'McDonald\'s', 'KFC'], explanation: 'McDonald\'s "I\'m Lovin\' It" campaign launched globally in 2003. Justin Timberlake recorded the original jingle, and it became the company\'s longest-running slogan.' },
  { id: 'pop-27', category: 'pop-culture', difficulty: 'easy', question: 'Which of these is NOT one of the original starter Pokemon in Red and Blue?', answer: 'Pikachu', options: ['Charmander', 'Squirtle', 'Pikachu', 'Bulbasaur'], explanation: 'The three original starters are Bulbasaur, Charmander, and Squirtle. Pikachu became a starter only in Pokemon Yellow, which was based on the anime series.' },
  { id: 'pop-28', category: 'pop-culture', difficulty: 'easy', question: 'What streaming service produced the series "Stranger Things"?', answer: 'Netflix', options: ['Hulu', 'Netflix', 'Amazon Prime', 'HBO Max'], explanation: 'Stranger Things premiered on Netflix in 2016 and became a massive cultural phenomenon. The show is set in the 1980s in the fictional town of Hawkins, Indiana.' },
  { id: 'pop-29', category: 'pop-culture', difficulty: 'easy', question: 'What social networking site dominated the mid-2000s and was especially important for music discovery?', answer: 'Myspace', options: ['Friendster', 'Myspace', 'Facebook', 'Hi5'], explanation: 'Myspace launched in August 2003 and dominated social media from 2005 to 2009. It was especially important for music discovery, helping launch artists like Arctic Monkeys.' },
  { id: 'pop-30', category: 'pop-culture', difficulty: 'easy', question: 'What brand\'s logo features a swoosh?', answer: 'Nike', options: ['Adidas', 'Nike', 'Puma', 'Reebok'], explanation: 'The Nike Swoosh was designed by graphic design student Carolyn Davidson in 1971 for just $35. Phil Knight reportedly said he didn\'t love it but thought it would grow on him.' },
  { id: 'pop-31', category: 'pop-culture', difficulty: 'easy', question: 'What awards show gives out golden statuettes called "Oscars"?', answer: 'The Academy Awards', options: ['The Golden Globes', 'The Academy Awards', 'The Emmy Awards', 'The Grammy Awards'], explanation: 'The Academy Awards have been presented since 1929 by the Academy of Motion Picture Arts and Sciences. The gold-plated statuette is officially called the Academy Award of Merit.' },
  { id: 'pop-32', category: 'pop-culture', difficulty: 'easy', question: 'What was the short-form video app that was shut down by Twitter in 2017?', answer: 'Vine', options: ['Vine', 'TikTok', 'Dubsmash', 'Musical.ly'], explanation: 'Vine allowed users to create and share six-second looping video clips. Many popular internet creators got their start on Vine before migrating to YouTube and other platforms.' },
  { id: 'pop-33', category: 'pop-culture', difficulty: 'easy', question: 'What company makes the PlayStation gaming console?', answer: 'Sony', options: ['Microsoft', 'Nintendo', 'Sony', 'Sega'], explanation: 'Sony released the first PlayStation in 1994, entering the console market against Sega and Nintendo. The PlayStation brand has since sold over 500 million consoles worldwide.' },
  { id: 'pop-34', category: 'pop-culture', difficulty: 'easy', question: 'What classic board game has players calling out coordinates to sink ships?', answer: 'Battleship', options: ['Risk', 'Stratego', 'Battleship', 'Mastermind'], explanation: 'Battleship originated as a pencil-and-paper game from World War I. Milton Bradley released the plastic board game version in 1967, with the iconic phrase "You sunk my battleship!"' },
  { id: 'pop-35', category: 'pop-culture', difficulty: 'easy', question: 'What company did Steve Jobs co-found in a garage in 1976?', answer: 'Apple', options: ['Microsoft', 'Apple', 'IBM', 'Hewlett-Packard'], explanation: 'Steve Jobs co-founded Apple with Steve Wozniak and Ronald Wayne. The Apple I was hand-built by Wozniak and sold for $666.66.' },
  { id: 'pop-36', category: 'pop-culture', difficulty: 'medium', question: 'What year did Instagram launch?', answer: '2010', options: ['2008', '2010', '2012', '2014'], explanation: 'Instagram was created by Kevin Systrom and Mike Krieger and launched on October 6, 2010. Facebook acquired it in 2012 for approximately $1 billion.' },
  { id: 'pop-37', category: 'pop-culture', difficulty: 'medium', question: 'In Minecraft, what material do you need to mine diamonds?', answer: 'Iron pickaxe or better', options: ['Stone pickaxe', 'Iron pickaxe or better', 'Gold pickaxe', 'Wooden pickaxe'], explanation: 'Diamonds require at least an iron pickaxe to mine. Using a lower-tier pickaxe will break the diamond ore block without dropping anything. Diamonds are found below Y-level 16.' },
  { id: 'pop-38', category: 'pop-culture', difficulty: 'medium', question: 'What was the first video ever uploaded to YouTube?', answer: 'Me at the zoo', options: ['Charlie Bit My Finger', 'Me at the zoo', 'Evolution of Dance', 'Lazy Sunday'], explanation: 'Co-founder Jawed Karim uploaded "Me at the zoo" on April 23, 2005, filmed at the San Diego Zoo. The 18-second clip features Karim talking about elephants.' },
  { id: 'pop-39', category: 'pop-culture', difficulty: 'medium', question: 'What is the name of the princess in the original Legend of Zelda?', answer: 'Zelda', options: ['Link', 'Zelda', 'Saria', 'Impa'], explanation: 'Princess Zelda is the titular character, though players control Link. Series creator Shigeru Miyamoto named her after Zelda Fitzgerald, wife of author F. Scott Fitzgerald.' },
  { id: 'pop-40', category: 'pop-culture', difficulty: 'medium', question: 'Which tech billionaire co-founded Microsoft with Bill Gates?', answer: 'Paul Allen', options: ['Steve Ballmer', 'Paul Allen', 'Steve Wozniak', 'Larry Ellison'], explanation: 'Paul Allen and Bill Gates founded Microsoft in 1975 in Albuquerque, New Mexico. Allen left Microsoft in 1983 due to health issues and later owned the Portland Trail Blazers and Seattle Seahawks.' },
  { id: 'pop-41', category: 'pop-culture', difficulty: 'medium', question: 'What meme features a woman yelling at a confused white cat sitting at a dinner table?', answer: 'Woman Yelling at a Cat', options: ['Grumpy Cat', 'Woman Yelling at a Cat', 'Keyboard Cat', 'Nyan Cat'], explanation: 'This 2019 meme combines a screenshot of Taylor Armstrong from Real Housewives of Beverly Hills with a photo of a cat named Smudge. It became one of the most popular meme formats of that year.' },
  { id: 'pop-42', category: 'pop-culture', difficulty: 'medium', question: 'What fictional city is the setting for Grand Theft Auto: Vice City?', answer: 'A fictionalized Miami', options: ['A fictionalized New York', 'A fictionalized Miami', 'A fictionalized Los Angeles', 'A fictionalized Las Vegas'], explanation: 'Vice City is heavily inspired by 1980s Miami, complete with Art Deco architecture and a pastel color scheme. The game\'s story draws from Scarface and Miami Vice.' },
  { id: 'pop-43', category: 'pop-culture', difficulty: 'medium', question: 'What luxury fashion house uses a horse and carriage as its logo?', answer: 'Hermes', options: ['Burberry', 'Hermes', 'Coach', 'Ralph Lauren'], explanation: 'The Hermes logo depicts a Duc carriage with horse, reflecting the company\'s origins as a harness workshop in Paris in 1837. Hermes is famous for its Birkin and Kelly handbags.' },
  { id: 'pop-44', category: 'pop-culture', difficulty: 'medium', question: 'What was the first Pixar feature film?', answer: 'Toy Story', options: ['A Bug\'s Life', 'Toy Story', 'Finding Nemo', 'Monsters, Inc.'], explanation: 'Toy Story was released in 1995 and was the first entirely computer-animated feature film. It was directed by John Lasseter and produced in partnership with Disney.' },
  { id: 'pop-45', category: 'pop-culture', difficulty: 'medium', question: 'In what year did the original iPhone launch?', answer: '2007', options: ['2005', '2006', '2007', '2008'], explanation: 'Steve Jobs announced the iPhone on January 9, 2007, and it went on sale June 29. The original had a 3.5-inch screen, 2-megapixel camera, and no App Store (that came with iPhone 3G in 2008).' },
  { id: 'pop-46', category: 'pop-culture', difficulty: 'medium', question: 'What comic book character was created by Bob Kane and Bill Finger?', answer: 'Batman', options: ['Superman', 'Batman', 'Spider-Man', 'Wonder Woman'], explanation: 'Batman debuted in Detective Comics #27 in 1939. Bill Finger\'s crucial contributions to Batman\'s design and mythology went uncredited for decades until DC officially recognized him in 2015.' },
  { id: 'pop-47', category: 'pop-culture', difficulty: 'medium', question: 'What does "EGOT" stand for in entertainment?', answer: 'Emmy, Grammy, Oscar, Tony', options: ['Emmy, Globe, Oscar, Tony', 'Emmy, Grammy, Oscar, Tony', 'Emmy, Grammy, Ovation, Tony', 'Emmy, Grammy, Oscar, Triumph'], explanation: 'An EGOT winner has won all four major American entertainment awards. As of 2024, fewer than 20 people have achieved this feat, including Audrey Hepburn, Whoopi Goldberg, and John Legend.' },
  { id: 'pop-48', category: 'pop-culture', difficulty: 'medium', question: 'What was the name of the viral "dress" debate in 2015?', answer: 'The Dress (blue/black vs white/gold)', options: ['The Dress (blue/black vs white/gold)', 'The Shoe (pink/white vs gray/teal)', 'The Jacket (brown vs blue)', 'The Hat (green vs gray)'], explanation: 'A photo of a dress went viral in February 2015 because people genuinely saw different colors. The dress was actually blue and black, but differences in color perception made some see white and gold.' },
  { id: 'pop-49', category: 'pop-culture', difficulty: 'medium', question: 'What toy line features characters like Optimus Prime and Megatron?', answer: 'Transformers', options: ['G.I. Joe', 'Transformers', 'He-Man', 'Power Rangers'], explanation: 'Transformers launched in 1984 as a collaboration between Hasbro and Japanese company Takara. The toys featured robots that could transform into vehicles, with an accompanying cartoon series.' },
  { id: 'pop-50', category: 'pop-culture', difficulty: 'medium', question: 'What video game character is known for eating dots in a maze?', answer: 'Pac-Man', options: ['Pac-Man', 'Q*bert', 'Frogger', 'Dig Dug'], explanation: 'Pac-Man was created by Toru Iwatani and released by Namco in 1980. The character\'s shape was reportedly inspired by a pizza with a slice removed.' },
  { id: 'pop-51', category: 'pop-culture', difficulty: 'medium', question: 'What social media platform was known for disappearing messages and popularized the Stories format?', answer: 'Snapchat', options: ['Instagram', 'Snapchat', 'WhatsApp', 'Telegram'], explanation: 'Snapchat was created by Evan Spiegel, Bobby Murphy, and Reggie Brown at Stanford University in 2011. Instagram later copied the Stories feature in 2016, which became hugely popular.' },
  { id: 'pop-52', category: 'pop-culture', difficulty: 'medium', question: 'What is the name of the fictional country where Black Panther rules?', answer: 'Wakanda', options: ['Latveria', 'Wakanda', 'Genosha', 'Kamar-Taj'], explanation: 'Wakanda is a technologically advanced African nation powered by vibranium. Black Panther first appeared in Fantastic Four #52 in 1966, created by Stan Lee and Jack Kirby.' },
  { id: 'pop-53', category: 'pop-culture', difficulty: 'medium', question: 'What reality TV competition features fashion designers?', answer: 'Project Runway', options: ['America\'s Next Top Model', 'Project Runway', 'RuPaul\'s Drag Race', 'Making the Cut'], explanation: 'Project Runway premiered in 2004 on Bravo, hosted by Heidi Klum and mentored by Tim Gunn. Designers compete in challenges and face elimination with the phrase "You\'re out."' },
  { id: 'pop-54', category: 'pop-culture', difficulty: 'medium', question: 'What was the best-selling toy of the 1998 holiday season?', answer: 'Furby', options: ['Tickle Me Elmo', 'Furby', 'Beanie Babies', 'Tamagotchi'], explanation: 'Furbies were electronic robotic toys made by Tiger Electronics that appeared to learn English over time. Over 40 million Furbies were sold during the first three years of production.' },
  { id: 'pop-55', category: 'pop-culture', difficulty: 'medium', question: 'In GTA: San Andreas, what is the name of the main character?', answer: 'Carl "CJ" Johnson', options: ['Tommy Vercetti', 'Niko Bellic', 'Carl "CJ" Johnson', 'Claude Speed'], explanation: 'CJ returns to the fictional state of San Andreas after his mother\'s murder. San Andreas was released in 2004 and is set in a fictionalized version of California and Nevada.' },
  { id: 'pop-56', category: 'pop-culture', difficulty: 'medium', question: 'What brand has the slogan "Think Different"?', answer: 'Apple', options: ['Google', 'Apple', 'Samsung', 'Microsoft'], explanation: 'Apple\'s "Think Different" campaign launched in 1997, shortly after Steve Jobs returned to the company. The ads featured icons like Einstein, Gandhi, and Martin Luther King Jr.' },
  { id: 'pop-57', category: 'pop-culture', difficulty: 'medium', question: 'What internet meme features a Shiba Inu dog surrounded by comic sans text?', answer: 'Doge', options: ['Grumpy Cat', 'Doge', 'Cheems', 'Doggo'], explanation: 'The original Doge photo is of a Shiba Inu named Kabosu, taken by her owner in 2010. The meme inspired the cryptocurrency Dogecoin, created in 2013 as a joke that became surprisingly valuable.' },
  { id: 'pop-58', category: 'pop-culture', difficulty: 'medium', question: 'What is the highest-grossing film of all time (not adjusted for inflation)?', answer: 'Avatar (2009)', options: ['Avengers: Endgame', 'Avatar (2009)', 'Titanic', 'Star Wars: The Force Awakens'], explanation: 'Avatar earned over $2.9 billion worldwide, reclaiming the top spot after Avengers: Endgame briefly surpassed it. James Cameron directed both Avatar and Titanic, the #3 highest-grossing film.' },
  { id: 'pop-59', category: 'pop-culture', difficulty: 'medium', question: 'What company originally developed the Android operating system before Google acquired it?', answer: 'Android Inc.', options: ['Samsung', 'HTC', 'Android Inc.', 'Motorola'], explanation: 'Android Inc. was founded by Andy Rubin in 2003 and acquired by Google in 2005 for about $50 million. The first Android phone, the HTC Dream (T-Mobile G1), was released in 2008.' },
  { id: 'pop-60', category: 'pop-culture', difficulty: 'medium', question: 'What is the name of the AI assistant created by Amazon?', answer: 'Alexa', options: ['Siri', 'Cortana', 'Alexa', 'Bixby'], explanation: 'Alexa was introduced with the Amazon Echo smart speaker in 2014. The name was chosen partly because the "X" sound is easy for the device to recognize in different accents.' },
  { id: 'pop-61', category: 'pop-culture', difficulty: 'medium', question: 'What Disney theme park opened first?', answer: 'Disneyland', options: ['Disneyland', 'Walt Disney World', 'Tokyo Disneyland', 'Disneyland Paris'], explanation: 'Disneyland opened on July 17, 1955, in Anaheim, California. Walt Disney himself oversaw its construction. Walt Disney World in Florida didn\'t open until 1971, after Walt\'s death in 1966.' },
  { id: 'pop-62', category: 'pop-culture', difficulty: 'medium', question: 'What color is the ghost Blinky in Pac-Man?', answer: 'Red', options: ['Pink', 'Red', 'Blue', 'Orange'], explanation: 'Blinky is the red ghost and the most aggressive pursuer in Pac-Man. The four ghosts are Blinky (red), Pinky (pink), Inky (blue), and Clyde (orange), each with different chasing behaviors.' },
  { id: 'pop-63', category: 'pop-culture', difficulty: 'medium', question: 'What was Reddit\'s original mascot name?', answer: 'Snoo', options: ['Freddit', 'Snoo', 'Redd', 'Alien'], explanation: 'Snoo was drawn by Reddit co-founder Alexis Ohanian. The name comes from "what\'s new" — which is what the site aims to show users. Reddit was founded in 2005.' },
  { id: 'pop-64', category: 'pop-culture', difficulty: 'medium', question: 'In Pokemon, what type is super effective against Water?', answer: 'Electric', options: ['Fire', 'Electric', 'Ice', 'Rock'], explanation: 'Electric and Grass types are both super effective against Water. The type matchup system is central to Pokemon strategy, with 18 types creating a complex web of strengths and weaknesses.' },
  { id: 'pop-65', category: 'pop-culture', difficulty: 'medium', question: 'What year was the first tweet ever posted?', answer: '2006', options: ['2004', '2005', '2006', '2007'], explanation: 'Jack Dorsey posted the first tweet on March 21, 2006: "just setting up my twttr." He later sold it as an NFT in 2021 for $2.9 million.' },
  { id: 'pop-66', category: 'pop-culture', difficulty: 'medium', question: 'What fast food chain uses the slogan "Have It Your Way"?', answer: 'Burger King', options: ['McDonald\'s', 'Burger King', 'Wendy\'s', 'Subway'], explanation: 'Burger King introduced "Have It Your Way" in 1974 to differentiate from McDonald\'s standardized preparation. The slogan was later updated to "Be Your Way" in 2014.' },
  { id: 'pop-67', category: 'pop-culture', difficulty: 'medium', question: 'Who created the viral video series "Charlie the Unicorn"?', answer: 'Jason Steele (FilmCow)', options: ['Freddie Wong', 'Jason Steele (FilmCow)', 'Olan Rogers', 'Brandon Laatsch'], explanation: 'Charlie the Unicorn was created by Jason Steele and uploaded in 2005. The absurdist animated short about a unicorn tricked by two companions became one of early YouTube\'s biggest viral hits.' },
  { id: 'pop-68', category: 'pop-culture', difficulty: 'medium', question: 'What board game, created in 1965, requires players to perform operations without buzzing?', answer: 'Operation', options: ['Mousetrap', 'Operation', 'Don\'t Wake Daddy', 'Perfection'], explanation: 'Operation was invented by John Spinello as a college class project around 1964. He sold the concept to Milton Bradley for $500 and never received royalties on the multi-million dollar product. Milton Bradley released the game in 1965.' },
  { id: 'pop-69', category: 'pop-culture', difficulty: 'medium', question: 'What was the first massively multiplayer online game to reach 10 million subscribers?', answer: 'World of Warcraft', options: ['EverQuest', 'World of Warcraft', 'RuneScape', 'Final Fantasy XI'], explanation: 'World of Warcraft launched in 2004 by Blizzard Entertainment and peaked at over 12 million subscribers in 2010. It popularized the MMO genre and became a cultural phenomenon.' },
  { id: 'pop-70', category: 'pop-culture', difficulty: 'medium', question: 'What YouTube channel was the first to reach 100 million subscribers?', answer: 'T-Series', options: ['PewDiePie', 'T-Series', 'MrBeast', 'Cocomelon'], explanation: 'T-Series, an Indian music and film production company, surpassed PewDiePie in 2019 after a highly publicized subscriber race. The battle spawned the viral song "Congratulations" by PewDiePie.' },
  { id: 'pop-71', category: 'pop-culture', difficulty: 'medium', question: 'What tech company\'s motto was formerly "Don\'t be evil"?', answer: 'Google', options: ['Apple', 'Google', 'Facebook', 'Microsoft'], explanation: 'Google adopted "Don\'t be evil" as an informal corporate motto in its early days. When Google reorganized under Alphabet in 2015, the parent company\'s code of conduct changed to "Do the right thing."' },
  { id: 'pop-72', category: 'pop-culture', difficulty: 'medium', question: 'What is the name of the princess that Mario typically rescues?', answer: 'Princess Peach', options: ['Princess Daisy', 'Princess Peach', 'Princess Rosalina', 'Princess Zelda'], explanation: 'Princess Peach Toadstool rules the Mushroom Kingdom and is frequently captured by Bowser. In early American releases, she was known simply as "Princess Toadstool" before Peach became standard.' },
  { id: 'pop-73', category: 'pop-culture', difficulty: 'medium', question: 'What reality TV show coined the phrase "You\'re fired!"?', answer: 'The Apprentice', options: ['Shark Tank', 'The Apprentice', 'Dragon\'s Den', 'Undercover Boss'], explanation: 'The Apprentice premiered in 2004 with Donald Trump as the host. Contestants competed in business tasks, with one being eliminated each week with Trump\'s signature catchphrase.' },
  { id: 'pop-74', category: 'pop-culture', difficulty: 'medium', question: 'What fashion brand is known for its iconic tartan plaid pattern?', answer: 'Burberry', options: ['Burberry', 'Gucci', 'Versace', 'Fendi'], explanation: 'Burberry\'s iconic check pattern was created in the 1920s as a lining for trench coats. Thomas Burberry founded the company in 1856 and also invented gabardine, a waterproof yet breathable fabric.' },
  { id: 'pop-75', category: 'pop-culture', difficulty: 'medium', question: 'What is the best-selling game console of all time?', answer: 'PlayStation 2', options: ['Nintendo Wii', 'PlayStation 2', 'Xbox 360', 'Nintendo DS'], explanation: 'The PlayStation 2 sold over 160 million units worldwide, making it the best-selling console of all time. Released in 2000, it also functioned as a DVD player, which helped drive its massive adoption.' },
  { id: 'pop-76', category: 'pop-culture', difficulty: 'medium', question: 'What does the "E" in E3 stand for?', answer: 'Electronic Entertainment Expo', options: ['Electronic Entertainment Expo', 'Entertainment and Electronics Exhibition', 'Electronic Experience Event', 'Entertainment Enterprise Expo'], explanation: 'E3 was the biggest annual trade event for the video game industry, held in Los Angeles from 1995 to 2023. The ESA announced the cancellation of E3 permanently in 2023.' },
  { id: 'pop-77', category: 'pop-culture', difficulty: 'medium', question: 'What search engine did Larry Page and Sergey Brin create at Stanford?', answer: 'Google', options: ['Yahoo', 'Google', 'AltaVista', 'Bing'], explanation: 'Page and Brin developed Google as a research project in 1996, originally called "BackRub." The name Google is a play on "googol," the number 1 followed by 100 zeros.' },
  { id: 'pop-78', category: 'pop-culture', difficulty: 'medium', question: 'In The Legend of Zelda: Ocarina of Time, what instrument does Link play?', answer: 'An ocarina', options: ['A flute', 'A harp', 'An ocarina', 'A lute'], explanation: 'The Ocarina of Time allows Link to manipulate time and teleport. After the game\'s 1998 release, real ocarina sales surged worldwide as fans wanted to play the in-game songs.' },
  { id: 'pop-79', category: 'pop-culture', difficulty: 'medium', question: 'What cereal brand uses the slogan "They\'re Gr-r-reat!"?', answer: 'Frosted Flakes', options: ['Corn Flakes', 'Frosted Flakes', 'Froot Loops', 'Lucky Charms'], explanation: 'Tony the Tiger has been the Frosted Flakes mascot since 1952. Voice actor Thurl Ravenscroft provided Tony\'s iconic voice from 1952 to 2005, and the character has remained largely unchanged.' },
  { id: 'pop-80', category: 'pop-culture', difficulty: 'medium', question: 'What viral challenge involved dumping ice water over your head for charity?', answer: 'ALS Ice Bucket Challenge', options: ['The Cinnamon Challenge', 'ALS Ice Bucket Challenge', 'The Mannequin Challenge', 'The Tide Pod Challenge'], explanation: 'The ALS Ice Bucket Challenge went viral in summer 2014 and raised over $115 million for ALS research. The campaign led directly to the discovery of a gene linked to ALS called NEK1.' },
  { id: 'pop-81', category: 'pop-culture', difficulty: 'medium', question: 'What was the first iPhone model to remove the headphone jack?', answer: 'iPhone 7', options: ['iPhone 6S', 'iPhone 7', 'iPhone 8', 'iPhone X'], explanation: 'Apple removed the 3.5mm headphone jack with the iPhone 7 in 2016, sparking widespread controversy. Apple included Lightning EarPods and a dongle adapter in the box as alternatives.' },
  { id: 'pop-82', category: 'pop-culture', difficulty: 'medium', question: 'What is the name of the land where all the rides are in Universal\'s Harry Potter attraction?', answer: 'The Wizarding World of Harry Potter', options: ['Hogwarts Land', 'The Wizarding World of Harry Potter', 'Potterworld', 'Diagon District'], explanation: 'The Wizarding World of Harry Potter opened at Universal Orlando\'s Islands of Adventure in 2010. It features Hogwarts Castle, the village of Hogsmeade, and later expanded to include Diagon Alley.' },
  { id: 'pop-83', category: 'pop-culture', difficulty: 'medium', question: 'What popular battle royale game was developed by Epic Games?', answer: 'Fortnite', options: ['PUBG', 'Fortnite', 'Apex Legends', 'Call of Duty: Warzone'], explanation: 'Fortnite Battle Royale launched in 2017 and became a global phenomenon, especially among younger players. Its building mechanic and frequent pop culture crossovers set it apart from competitors.' },
  { id: 'pop-84', category: 'pop-culture', difficulty: 'medium', question: 'What is the name of the main character in the Legend of Zelda: Breath of the Wild?', answer: 'Link', options: ['Zelda', 'Link', 'Ganondorf', 'Sheik'], explanation: 'Despite the series being called "The Legend of Zelda," the playable hero is Link. Breath of the Wild, released in 2017, was a critical and commercial smash that reinvented the open-world genre.' },
  { id: 'pop-85', category: 'pop-culture', difficulty: 'medium', question: 'What brand logo features a three-pointed star inside a circle?', answer: 'Mercedes-Benz', options: ['BMW', 'Mercedes-Benz', 'Volkswagen', 'Audi'], explanation: 'The three-pointed star represents Mercedes-Benz\'s ambition to dominate transport on land, sea, and air. The company was named after Mercedes Jellinek, the daughter of an early automobile dealer.' },
  { id: 'pop-86', category: 'pop-culture', difficulty: 'medium', question: 'What was the name of the dance move that became a viral meme in Fortnite?', answer: 'The Floss', options: ['The Dab', 'The Floss', 'The Orange Justice', 'The Macarena'], explanation: 'The Floss was popularized by "Backpack Kid" Russell Horning during a Katy Perry performance in 2017. Epic Games added it to Fortnite, leading to a lawsuit from Horning over use of the dance.' },
  { id: 'pop-87', category: 'pop-culture', difficulty: 'medium', question: 'What Minecraft mob explodes when it gets close to the player?', answer: 'Creeper', options: ['Zombie', 'Creeper', 'Skeleton', 'Enderman'], explanation: 'The Creeper was actually created by accident when Notch tried to make a pig model and mixed up the height and length values. It has become the unofficial mascot of Minecraft.' },
  { id: 'pop-88', category: 'pop-culture', difficulty: 'medium', question: 'What is the highest rank in competitive chess?', answer: 'Grandmaster', options: ['Master', 'Grandmaster', 'International Master', 'Champion'], explanation: 'Grandmaster is a title awarded by FIDE, the international chess federation. The youngest person to achieve the title was Sergey Karjakin at age 12 years and 7 months in 2002.' },
  { id: 'pop-89', category: 'pop-culture', difficulty: 'medium', question: 'What Pokemon evolves into Charizard?', answer: 'Charmeleon', options: ['Charmander', 'Charmeleon', 'Charizard', 'Magmar'], explanation: 'The evolution chain goes Charmander -> Charmeleon -> Charizard. Charmeleon evolves at level 36, and Charizard is a Fire/Flying type despite looking like a dragon.' },
  { id: 'pop-90', category: 'pop-culture', difficulty: 'medium', question: 'What company makes the Kindle e-reader?', answer: 'Amazon', options: ['Apple', 'Barnes & Noble', 'Amazon', 'Sony'], explanation: 'Amazon released the first Kindle in 2007, and it sold out in just 5.5 hours. The device uses E Ink technology that mimics the appearance of printed paper and is easy on the eyes.' },
  { id: 'pop-91', category: 'pop-culture', difficulty: 'hard', question: 'What was the original name of Snapchat when it launched in 2011?', answer: 'Picaboo', options: ['SnapShare', 'Picaboo', 'PhotoPop', 'FlashPic'], explanation: 'Evan Spiegel and Bobby Murphy launched the app as Picaboo in July 2011 before rebranding to Snapchat in September 2011. The app was created as a class project at Stanford University.' },
  { id: 'pop-92', category: 'pop-culture', difficulty: 'hard', question: 'What was the first video game to feature Mario, before he was named Mario?', answer: 'Donkey Kong', options: ['Mario Bros.', 'Donkey Kong', 'Super Mario Bros.', 'Wrecking Crew'], explanation: 'Mario first appeared as "Jumpman" in the 1981 arcade game Donkey Kong. He was named after Mario Segale, the landlord of Nintendo of America\'s warehouse, who once confronted them about late rent.' },
  { id: 'pop-93', category: 'pop-culture', difficulty: 'hard', question: 'What was the name of Google\'s failed social network that launched in 2011?', answer: 'Google+', options: ['Google Buzz', 'Google+', 'Google Wave', 'Google Spaces'], explanation: 'Google+ launched in 2011 to compete with Facebook but never gained mainstream traction. It was shut down in 2019 after a data breach exposed user information. Google Buzz and Wave were separate failed products.' },
  { id: 'pop-94', category: 'pop-culture', difficulty: 'hard', question: 'In the original Pokemon Red and Blue, what level does Magikarp evolve into Gyarados?', answer: '20', options: ['15', '20', '25', '30'], explanation: 'Magikarp is famously weak, knowing only Splash (which does nothing) until level 15 when it learns Tackle. At level 20, it evolves into the powerful Gyarados, making the grind worthwhile.' },
  { id: 'pop-95', category: 'pop-culture', difficulty: 'hard', question: 'What was the first product Amazon ever sold?', answer: 'A book', options: ['A CD', 'A book', 'A DVD', 'Electronics'], explanation: 'The first item sold on Amazon in July 1995 was a book called "Fluid Concepts and Creative Analogies" by Douglas Hofstadter. Jeff Bezos chose books because of the vast number of titles in print.' },
  { id: 'pop-96', category: 'pop-culture', difficulty: 'hard', question: 'What was the fictional company in the movie Wall-E that trashed the Earth?', answer: 'Buy n Large (BnL)', options: ['Omni Consumer Products', 'Buy n Large (BnL)', 'Massive Dynamic', 'Virtucon'], explanation: 'Buy n Large was a megacorporation that controlled all commerce and government on Earth before its pollution made the planet uninhabitable. The satire parallels real concerns about corporate consolidation.' },
  { id: 'pop-97', category: 'pop-culture', difficulty: 'hard', question: 'Who illustrated the very first Superman comic?', answer: 'Joe Shuster', options: ['Bob Kane', 'Joe Shuster', 'Jack Kirby', 'Steve Ditko'], explanation: 'Joe Shuster illustrated and Jerry Siegel wrote Action Comics #1, which introduced Superman in 1938. The two high school friends from Cleveland sold the rights to DC for just $130.' },
  { id: 'pop-98', category: 'pop-culture', difficulty: 'hard', question: 'What was the code name for the Nintendo Wii during development?', answer: 'Revolution', options: ['Dolphin', 'Revolution', 'Ultra', 'Project Cafe'], explanation: 'The Wii was code-named "Revolution" and the name change to "Wii" was controversial when announced. "Dolphin" was the GameCube\'s code name, and "Project Cafe" was the Wii U\'s.' },
  { id: 'pop-99', category: 'pop-culture', difficulty: 'hard', question: 'What early social network, launched in 2002, is considered the first to gain mainstream popularity?', answer: 'Friendster', options: ['Friendster', 'SixDegrees', 'Myspace', 'LiveJournal'], explanation: 'Friendster launched in 2002 and quickly gained millions of users before technical problems drove them away. SixDegrees (1997) was technically earlier but didn\'t achieve the same cultural impact.' },
  { id: 'pop-100', category: 'pop-culture', difficulty: 'hard', question: 'What is the Konami Code?', answer: 'Up, Up, Down, Down, Left, Right, Left, Right, B, A', options: ['Up, Down, Up, Down, Left, Right, Left, Right, A, B', 'Up, Up, Down, Down, Left, Right, Left, Right, B, A', 'Up, Up, Down, Down, Right, Left, Right, Left, B, A', 'Up, Down, Left, Right, Up, Down, Left, Right, A, B'], explanation: 'The Konami Code was created by Kazuhisa Hashimoto for the 1986 NES port of Gradius because the game was too hard. It has since appeared as an Easter egg in hundreds of games and websites.' },
  { id: 'pop-101', category: 'pop-culture', difficulty: 'hard', question: 'What year did the "Gangnam Style" music video become the first YouTube video to reach 1 billion views?', answer: '2012', options: ['2011', '2012', '2013', '2014'], explanation: 'PSY\'s "Gangnam Style" hit 1 billion views in December 2012, just five months after upload. It actually broke YouTube\'s view counter, which at the time used a 32-bit integer maxing at 2.1 billion.' },
  { id: 'pop-102', category: 'pop-culture', difficulty: 'hard', question: 'What was the first comic book to sell for over $1 million at auction?', answer: 'Action Comics #1', options: ['Detective Comics #27', 'Action Comics #1', 'Amazing Fantasy #15', 'Superman #1'], explanation: 'Action Comics #1, featuring Superman\'s debut, first sold for over $1 million in 2010. A near-mint copy later sold for $3.25 million in 2014. The original cover price was 10 cents.' },
  { id: 'pop-103', category: 'pop-culture', difficulty: 'hard', question: 'What was the original price of the game Minecraft when Notch first sold it in alpha?', answer: '€9.95', options: ['€4.95', '€9.95', '€14.95', '€19.95'], explanation: 'Minecraft\'s alpha was priced at €9.95 (about $13) when it first became available in 2009. The price gradually increased through development stages, reaching its current price at full release in 2011.' },
  { id: 'pop-104', category: 'pop-culture', difficulty: 'hard', question: 'What fashion designer\'s real name is Ralph Lifshitz?', answer: 'Ralph Lauren', options: ['Calvin Klein', 'Ralph Lauren', 'Tommy Hilfiger', 'Marc Jacobs'], explanation: 'Ralph Lauren, born Ralph Lifshitz in the Bronx in 1939, changed his surname as a teenager. He started his fashion empire by selling ties and built it into a multi-billion dollar brand.' },
  { id: 'pop-105', category: 'pop-culture', difficulty: 'hard', question: 'What was the first video game Easter egg, hidden in what 1980 Atari game?', answer: 'Adventure', options: ['Asteroids', 'Adventure', 'Pong', 'Space Invaders'], explanation: 'Programmer Warren Robinett hid a secret room displaying "Created by Warren Robinett" because Atari didn\'t credit developers. This is widely considered the first video game Easter egg.' },
  { id: 'pop-106', category: 'pop-culture', difficulty: 'hard', question: 'What does the "__(two underscores) face" emoticon that became a famous meme represent?', answer: 'ಠ_ಠ is the Look of Disapproval', options: ['ಠ_ಠ is the Look of Disapproval', '(╯°□°)╯ is the Table Flip', '¯\\_(ツ)_/¯ is the Shrug', '( ͡° ͜ʖ ͡°) is the Lenny Face'], explanation: 'The Look of Disapproval uses Kannada script characters and was popularized on Reddit around 2009. It became one of the most widely used text emoticons for expressing judgment or displeasure.' },
  { id: 'pop-107', category: 'pop-culture', difficulty: 'hard', question: 'What was the name of the AI chatbot that Microsoft released on Twitter in 2016 that quickly became offensive?', answer: 'Tay', options: ['Cortana', 'Tay', 'Xiaoice', 'Sydney'], explanation: 'Microsoft\'s Tay was designed to mimic a teenage girl and learn from Twitter interactions. Within 24 hours, internet trolls taught it to produce racist and inflammatory tweets, and Microsoft shut it down.' },
  { id: 'pop-108', category: 'pop-culture', difficulty: 'hard', question: 'What GTA game introduced the "Wanted Level" star system?', answer: 'Grand Theft Auto (1997)', options: ['Grand Theft Auto (1997)', 'Grand Theft Auto III', 'Grand Theft Auto: Vice City', 'Grand Theft Auto: San Andreas'], explanation: 'The original 1997 top-down Grand Theft Auto introduced the wanted level system using stars. The system has been refined in each sequel but the core concept has remained the same.' },
  { id: 'pop-109', category: 'pop-culture', difficulty: 'hard', question: 'What was the name of the handheld console that Sega released to compete with the Game Boy?', answer: 'Game Gear', options: ['Sega Nomad', 'Game Gear', 'Neo Geo Pocket', 'Lynx'], explanation: 'The Sega Game Gear launched in 1990 with a backlit color screen, a major advantage over the Game Boy\'s green monochrome display. Despite this, the Game Boy outsold it due to better battery life and games.' },
  { id: 'pop-110', category: 'pop-culture', difficulty: 'hard', question: 'What was the original meaning of the word "meme" as coined by Richard Dawkins?', answer: 'A unit of cultural information that spreads by imitation', options: ['A funny image shared online', 'A unit of cultural information that spreads by imitation', 'A viral video on the internet', 'A humorous text with an image overlay'], explanation: 'Richard Dawkins coined "meme" in his 1976 book "The Selfish Gene," combining the Greek word "mimeme" (imitated thing) with "gene." He described memes as cultural equivalents of genes.' },
  { id: 'pop-111', category: 'pop-culture', difficulty: 'hard', question: 'What brand originally made rubber-soled shoes called "Keds" before becoming famous for something else?', answer: 'Keds was its own brand; the question refers to what company made the first sneakers', options: ['Nike', 'Converse', 'Keds was its own brand; the question refers to what company made the first sneakers', 'Adidas'], explanation: 'Trick detail — Keds, released in 1916 by U.S. Rubber Company, is widely considered one of the first mass-marketed canvas sneakers. Converse released the All Star in 1917, making them close competitors for "first sneaker" status.' },
  { id: 'pop-112', category: 'pop-culture', difficulty: 'hard', question: 'What year was the first E3 (Electronic Entertainment Expo) held?', answer: '1995', options: ['1993', '1995', '1997', '1999'], explanation: 'The first E3 took place in May 1995 in Los Angeles. Major announcements at the first event included the Sega Saturn surprise launch and the debut of the original PlayStation in North America.' },
  { id: 'pop-113', category: 'pop-culture', difficulty: 'hard', question: 'What was the most expensive domain name ever sold (as of 2024)?', answer: 'Cars.com', options: ['Insurance.com', 'Cars.com', 'Sex.com', 'Voice.com'], explanation: 'Cars.com sold for approximately $872 million in 2014 as part of a business acquisition deal. Among pure domain-only sales, Voice.com sold for $30 million in 2019.' },
  { id: 'pop-114', category: 'pop-culture', difficulty: 'hard', question: 'In what Legend of Zelda game did the Master Sword first appear?', answer: 'A Link to the Past', options: ['The Legend of Zelda', 'Zelda II: The Adventure of Link', 'A Link to the Past', 'Ocarina of Time'], explanation: 'The Master Sword debuted in 1991\'s A Link to the Past for the Super Nintendo. It has since appeared in most Zelda games and is one of the most iconic weapons in gaming history.' },
  { id: 'pop-115', category: 'pop-culture', difficulty: 'hard', question: 'What was the first reality TV show to air on American television?', answer: 'An American Family (1973)', options: ['The Real World (1992)', 'An American Family (1973)', 'Candid Camera (1948)', 'Cops (1989)'], explanation: 'An American Family aired on PBS in 1973 and documented the Loud family of Santa Barbara. It is considered the first reality TV show, though Candid Camera (1948) pioneered hidden camera concepts earlier.' },
  { id: 'pop-116', category: 'pop-culture', difficulty: 'hard', question: 'What company made the Tamagotchi virtual pet?', answer: 'Bandai', options: ['Nintendo', 'Bandai', 'Sega', 'Tiger Electronics'], explanation: 'Bandai released the Tamagotchi in 1996 in Japan, created by Aki Maita and Akihiro Yokoi. Over 82 million units were sold worldwide in its first few years, becoming a 1990s cultural icon.' },
  { id: 'pop-117', category: 'pop-culture', difficulty: 'hard', question: 'What was the name of the internet browser that came pre-installed on most Windows computers in the late 1990s?', answer: 'Internet Explorer', options: ['Netscape Navigator', 'Internet Explorer', 'Mozilla Firefox', 'AOL Browser'], explanation: 'Microsoft bundled Internet Explorer with Windows, leading to the "Browser Wars" with Netscape. This practice was central to the landmark United States v. Microsoft antitrust case in 1998.' },
  { id: 'pop-118', category: 'pop-culture', difficulty: 'hard', question: 'What Pokemon was accidentally made nearly impossible to catch in the original games, leading to myths about a truck near the S.S. Anne?', answer: 'Mew', options: ['Mewtwo', 'Mew', 'Celebi', 'Ditto'], explanation: 'Mew was secretly programmed into Pokemon Red/Blue by Shigeki Morimoto without permission. A rumor spread that Mew could be found under a truck near the S.S. Anne, though this was false.' },
  { id: 'pop-119', category: 'pop-culture', difficulty: 'hard', question: 'What was the first product that eBay founder Pierre Omidyar sold on the site?', answer: 'A broken laser pointer', options: ['A Pez dispenser', 'A broken laser pointer', 'A used book', 'A collectible coin'], explanation: 'Pierre Omidyar sold a broken laser pointer for $14.83 in 1995. When he contacted the buyer to make sure they knew it was broken, the buyer said they were a collector of broken laser pointers.' },
  { id: 'pop-120', category: 'pop-culture', difficulty: 'hard', question: 'What tech company was originally named "Blue Ribbon Sports"?', answer: 'Nike', options: ['Adidas', 'Nike', 'Under Armour', 'Reebok'], explanation: 'Phil Knight and Bill Bowerman founded Blue Ribbon Sports in 1964, importing Japanese running shoes. They rebranded to Nike in 1978, named after the Greek goddess of victory.' },
  { id: 'pop-121', category: 'pop-culture', difficulty: 'hard', question: 'What was the highest-grossing arcade game of all time?', answer: 'Pac-Man', options: ['Space Invaders', 'Pac-Man', 'Donkey Kong', 'Street Fighter II'], explanation: 'Pac-Man has generated over $14 billion in revenue (adjusted for inflation) since its 1980 release. Space Invaders comes in second. Pac-Man was also the first game to inspire widespread merchandising.' },
  { id: 'pop-122', category: 'pop-culture', difficulty: 'hard', question: 'What year did Wikipedia launch?', answer: '2001', options: ['1999', '2001', '2003', '2005'], explanation: 'Wikipedia launched on January 15, 2001, founded by Jimmy Wales and Larry Sanger. It grew from a complement to the expert-written Nupedia project and now contains over 60 million articles across 300+ languages.' },
  { id: 'pop-123', category: 'pop-culture', difficulty: 'hard', question: 'What is the real name of the YouTuber PewDiePie?', answer: 'Felix Kjellberg', options: ['Felix Kjellberg', 'Daniel Middleton', 'Mark Fischbach', 'Sean McLoughlin'], explanation: 'Felix Kjellberg is a Swedish YouTuber who was the platform\'s most-subscribed individual creator for years. Daniel Middleton is DanTDM, Mark Fischbach is Markiplier, and Sean McLoughlin is Jacksepticeye.' },
  { id: 'pop-124', category: 'pop-culture', difficulty: 'hard', question: 'What board game, first released in the 1940s, involves strategy on a grid with pieces of hidden rank?', answer: 'Stratego', options: ['Risk', 'Stratego', 'Chess', 'Axis & Allies'], explanation: 'Stratego was first distributed in 1946 in the Netherlands and is based on an earlier French game called L\'Attaque from 1909. Players arrange military pieces of hidden rank on a board and try to capture the opponent\'s flag. Milton Bradley introduced it to the US in 1961.' },
  { id: 'pop-125', category: 'pop-culture', difficulty: 'hard', question: 'What was Steve Jobs\' annual salary as CEO of Apple after he returned in 1997?', answer: '$1', options: ['$1', '$100,000', '$1 million', '$0'], explanation: 'Steve Jobs famously took a $1 annual salary when he returned to Apple, earning him a Guinness World Record for "Lowest Paid CEO." He was compensated instead through stock options and a private jet.' },
]
